CREATE TABLE bloc_emballage_cadeau
        (
            id INTEGER PRIMARY KEY AUTOINCREMENT, html_template TEXT
        );
INSERT INTO "bloc_emballage_cadeau" VALUES(1,'<!-- =========================
BLOC EMBALLAGE CADEAU - VERSION COMPACTE
========================= -->

<aside style="
margin:30px auto;
max-width:760px;
font-family:Arial,sans-serif;
border:1px solid #e2e8f0;
border-radius:24px;
overflow:hidden;
background:#ffffff;
box-shadow:0 10px 28px rgba(15,23,42,0.06);
">

    <header style="
    background:linear-gradient(135deg,#fbbf24,#d97706);
    color:white;
    padding:18px 22px;
    display:flex;
    justify-content:space-between;
    align-items:center;
    flex-wrap:wrap;
    gap:14px;
    ">

        <div>

            <div style="
            font-size:15px;
            font-weight:900;
            text-transform:uppercase;
            letter-spacing:0.6px;
            ">
                Produit éligible
            </div>

            <div style="
            margin-top:4px;
            font-size:13px;
            line-height:1.6;
            opacity:0.95;
            ">
                Service emballage cadeau disponible,
                avec préparation soignée à la main
            </div>

        </div>

        <div style="
        background:#ffffff;
        color:#c2410c;
        padding:10px 18px;
        border-radius:999px;
        font-size:14px;
        font-weight:900;
        white-space:nowrap;
        ">
            +{{prix_emballage_cadeau}} &#8364; TTC
        </div>

    </header>

    <div style="
    padding:18px 22px;
    ">

        <div style="
        display:grid;
        grid-template-columns:repeat(auto-fit,minmax(190px,1fr));
        gap:12px;
        ">

            <div style="
            background:#f8fafc;
            border:1px solid #e2e8f0;
            border-radius:14px;
            padding:14px 16px;
            ">
                <div style="
                font-size:14px;
                font-weight:900;
                color:#111827;
                ">
                    Emballage adapté
                </div>
                <div style="
                margin-top:6px;
                font-size:12px;
                line-height:1.7;
                color:#64748b;
                ">
                    Papier cadeau, pochette ou boîte premium
                    selon le volume du produit.
                </div>
            </div>

            <div style="
            background:#f8fafc;
            border:1px solid #e2e8f0;
            border-radius:14px;
            padding:14px 16px;
            ">
                <div style="
                font-size:14px;
                font-weight:900;
                color:#111827;
                ">
                    Présentation soignée
                </div>
                <div style="
                margin-top:6px;
                font-size:12px;
                line-height:1.7;
                color:#64748b;
                ">
                    Préparation propre et soignée à la main,
                    prête à offrir directement.
                </div>
            </div>

            <div style="
            background:#f8fafc;
            border:1px solid #e2e8f0;
            border-radius:14px;
            padding:14px 16px;
            ">
                <div style="
                font-size:14px;
                font-weight:900;
                color:#111827;
                ">
                    Surprise préservée
                </div>
                <div style="
                margin-top:6px;
                font-size:12px;
                line-height:1.7;
                color:#64748b;
                ">
                    La facture est envoyée par email à l''acheteur,
                    jamais glissée dans le colis.
                </div>
            </div>

        </div>

        <p style="
        margin:14px 0 0 0;
        font-size:11px;
        line-height:1.7;
        color:#94a3b8;
        ">
            Service réservé aux produits en stock, hors articles
            surdimensionnés.
        </p>

    </div>

</aside>');
