INSERT OR REPLACE INTO "produits" VALUES(29,'8445484529579','S000020','stock','Bonnet en maille Jack Skellington – L''Étrange Noël de Monsieur Jack',24,NULL,NULL,24,7,'2200010577',4.25,NULL,NULL,NULL,22.0,2.0,21.0,0.0,'Maille','Blanc à motif noir',0,'',NULL,NULL,'Affichez votre passion pour l''univers de L''Étrange Noël de Monsieur Jack avec ce bonnet en acrylique à l''effigie de Jack Skellington. Confectionné en maille.','Bonnet Jack Skellington : l''univers de L''Étrange Noël de Monsieur Jack jusque dans votre look

