INSERT OR REPLACE INTO "produits" VALUES(94,'5028486485352','S000085','stock','Coffret Friends Gribouillages - Verre XXL + Mug + 2 sous-verres',34,NULL,NULL,41,2,'GFB0099',12.49,NULL,NULL,NULL,22.0,16.5,10.0,1.09,'','',0,'',NULL,NULL,'Coffret Friends avec verre XXL, mug et 2 sous-verres au design Gribouillages. Une idée cadeau originale pour les fans de la série.','Un coffret Friends pour les fans de la série culte
