INSERT OR REPLACE INTO "produits" VALUES(172,'0889698946926','S000161','stock','Funko Pop! KPop Demon Hunters – Rumi #2257',53,NULL,NULL,55,4,'FUN94692',8.95,NULL,NULL,NULL,16.0,11.5,9.0,0.17,'Vinyle','',0,'',NULL,NULL,'Retrouvez Rumi de HUNTR/X avec cette Funko Pop! KPop Demon Hunters #2257 en vinyle, une figurine à collectionner ou à offrir.','Rumi de KPop Demon Hunters en Funko Pop!
