INSERT OR REPLACE INTO "produits" VALUES(188,'8435497261047','S000177','stock','Classeur 4 anneaux Premium Dragon Ball – Format A4',41,NULL,NULL,37,18,'CAT0087',2.15,NULL,NULL,NULL,32.0,27.5,4.0,0.4,'','',0,'',NULL,NULL,'Organisez vos documents avec ce classeur A4 Premium Dragon Ball à 4 anneaux, doté d’une couverture rigide et d’une fermeture élastique.','Un classeur Premium aux couleurs de Dragon Ball
