INSERT OR REPLACE INTO "produits" VALUES(203,'8435747814184','S000192','stock','Carnet Harry Potter en simili cuir – Vif d''Or',26,NULL,NULL,22,18,'CUPI02',4.94,NULL,NULL,NULL,21.0,16.0,2.0,0.42,'','',0,'',NULL,NULL,'Confiez vos notes à ce carnet Harry Potter Vif d''Or en simili cuir, avec 180 pages crème recyclées, reliure cousue et fermeture latérale.','Un carnet Harry Potter inspiré du Vif d''Or
