INSERT OR REPLACE INTO "produits" VALUES(206,'8435497297374','S000195','stock','Carnet A5 Premium lumineux Marvel Deadpool',21,NULL,NULL,17,18,'CPA5046',3.5,NULL,NULL,NULL,21.0,16.0,2.0,0.5,'','',0,'',NULL,NULL,'Notez vos idées avec ce carnet A5 Marvel Deadpool de 192 pages doté d’une couverture lumineuse LED et d’un stylo inclus.','Un carnet Deadpool qui s''illumine
