INSERT OR REPLACE INTO "produits" VALUES(214,'8435747808206','S000203','stock','Trousse 3D Harry Potter – Harry',26,NULL,NULL,22,18,'MARE0329',6.59,NULL,NULL,NULL,19.7,8.7,8.6,0.3,'Silicone','',0,'',NULL,NULL,'Une trousse 3D Harry Potter en silicone avec base extensible, idéale pour ranger crayons et stylos tout en affichant sa passion pour Poudlard.','Une trousse 3D aux couleurs de Harry Potter
