INSERT OR REPLACE INTO "produits" VALUES(217,'8435497295257','S000206','stock','Trousse 3 compartiments Disney Stitch Just Chill',28,NULL,NULL,30,18,'MARE0285',5.35,NULL,NULL,NULL,22.0,12.5,2.0,0.1,'Polyester','',0,'',NULL,NULL,'Une trousse Disney Stitch Just Chill avec 3 compartiments pratiques pour organiser crayons, stylos et petites fournitures scolaires.','Une trousse Stitch pleine de couleurs
