CREATE TABLE regles_template_periode
        (
            id INTEGER PRIMARY KEY AUTOINCREMENT, nom TEXT, periode_id INTEGER, modele_fiche_id INTEGER, categorie_site_id INTEGER, priorite INTEGER DEFAULT 0, actif INTEGER DEFAULT 1
        , type_produit TEXT);
CREATE TABLE renouvellement_stock
        (
            id INTEGER PRIMARY KEY AUTOINCREMENT, ajustement_manuel REAL DEFAULT 0
        );
INSERT INTO "renouvellement_stock" VALUES(1,15000.0);
CREATE TABLE roles
        (
            id INTEGER PRIMARY KEY AUTOINCREMENT, nom TEXT UNIQUE, description TEXT
        );
CREATE TABLE roles_permissions
        (
            id INTEGER PRIMARY KEY AUTOINCREMENT, role_id INTEGER, permission_id INTEGER
        );
CREATE TABLE sauvegardes
        (
            id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT, nom_fichier TEXT, taille INTEGER, type TEXT, commentaire TEXT
        );
CREATE TABLE sav
        (
            id INTEGER PRIMARY KEY AUTOINCREMENT, numero TEXT UNIQUE, commande_id INTEGER, client_id INTEGER, produit_id INTEGER, date_ouverture TEXT, date_cloture TEXT, motif TEXT, statut TEXT, solution TEXT, montant REAL, commentaire TEXT
        );
CREATE TABLE soldes_journaliers
        (
            id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT UNIQUE, solde_ttc REAL, actif INTEGER DEFAULT 1
        );
