INSERT INTO "themes_template" VALUES(15,'LANDING PAGE CATEGORIE A TERMINER','<!DOCTYPE html> 
<html lang="fr"> 
<head> 
<meta charset="UTF-8"> 
<meta name="viewport" content="width=device-width, initial-scale=1.0"> 
  
<title>Spider-Man | Pop Licence</title> 
  
<meta name="description" content="Découvrez la collection officielle Spider-Man sur Pop Licence : vêtements, figurines, accessoires, sacs, pyjamas et idées cadeaux Marvel sous licence officielle."> 
  
<style> 
  
/* ========================= 
BASE 
========================= */ 
  
body{ 
margin:0; 
background:#f8fafc; 
font-family:Arial,sans-serif; 
color:#111827; 
} 
  
*{ 
box-sizing:border-box; 
} 
  
a{ 
text-decoration:none; 
color:inherit; 
} 
  
.container{ 
max-width:1300px; 
margin:auto; 
padding:0 20px; 
} 
  
/* ========================= 
HERO 
========================= */ 
  
.hero{ 
position:relative; 
overflow:hidden; 
padding:90px 20px; 
background: 
linear-gradient(135deg,rgba(15,23,42,0.92),rgba(30,64,175,0.82)), 
url(''https://i.postimg.cc/t4VSknD3/cosplay-images-spiderman-7244196-1280.jpg'') center/cover; 
color:white; 
text-align:center; 
} 
  
.hero::before{ 
content:""; 
position:absolute; 
top:-120px; 
right:-120px; 
width:320px; 
height:320px; 
border-radius:50%; 
background:rgba(255,255,255,0.05); 
} 
  
  
.hero::after{ 
content:""; 
position:absolute; 
bottom:-100px; 
left:-100px; 
width:260px; 
height:260px; 
border-radius:50%; 
background:rgba(255,255,255,0.04); 
} 
  
.hero-content{ 
position:relative; 
z-index:2; 
max-width:900px; 
margin:auto; 
} 
  
.hero-badge{ 
display:inline-block; 
background:#fbbf24; 
color:#111827; 
padding:10px 18px; 
border-radius:999px; 
font-size:12px; 
font-weight:900; 
text-transform:uppercase; 
letter-spacing:1px; 
margin-bottom:24px; 
} 
  
.hero h1{ 
margin:0; 
font-size:clamp(42px,7vw,74px); 
line-height:1.05; 
font-weight:900; 
text-transform:uppercase; 
} 
  
.hero p{ 
margin:26px auto 0 auto; 
max-width:760px; 
font-size:18px; 
line-height:2; 
color:rgba(255,255,255,0.92); 
} 
  
.hero-tags{ 
display:flex; 
justify-content:center; 
flex-wrap:wrap; 
gap:14px; 
margin-top:34px; 
} 
  
.hero-tag{ 
background:rgba(255,255,255,0.10); 
border:1px solid rgba(255,255,255,0.14); 
padding:10px 16px; 
border-radius:999px; 
font-size:13px; 
font-weight:700; 
} 
  
/* ========================= 
AVANTAGES 
========================= */ 
  
.benefits{ 
margin-top:-34px; 
position:relative; 
z-index:5; 
} 
  
.benefits-grid{ 
display:grid; 
grid-template-columns:repeat(4,1fr); 
gap:18px; 
} 
  
.benefit-card{ 
background:white; 
padding:22px; 
border-radius:20px; 
text-align:center; 
box-shadow:0 10px 30px rgba(15,23,42,0.08); 
border:1px solid #e2e8f0; 
} 
  
.benefit-icon{ 
font-size:32px; 
margin-bottom:12px; 
} 
  
.benefit-card h3{ 
margin:0; 
font-size:15px; 
font-weight:900; 
color:#111827; 
} 
  
.benefit-card p{ 
margin:10px 0 0 0; 
font-size:13px; 
line-height:1.8; 
color:#64748b; 
} 
  
/* ========================= 
SOUS CATEGORIES 
========================= */ 
  
.section{ 
margin-top:70px; 
} 
  
.section-title{ 
margin:0; 
font-size:38px; 
font-weight:900; 
color:#111827; 
text-align:center; 
} 
  
.section-text{ 
margin:18px auto 0 auto; 
max-width:820px; 
font-size:15px; 
line-height:2; 
color:#64748b; 
text-align:center; 
} 
  
.categories-grid{ 
display:grid; 
grid-template-columns:repeat(4,1fr); 
gap:22px; 
margin-top:40px; 
} 
  
.category-card{ 
position:relative; 
overflow:hidden; 
border-radius:28px; 
height:320px; 
background:#111827; 
box-shadow:0 14px 34px rgba(15,23,42,0.12); 
transition:0.3s; 
} 
  
.category-card:hover{ 
transform:translateY(-8px); 
} 
  
.category-card img{ 
width:100%; 
height:100%; 
object-fit:cover; 
opacity:0.78; 
transition:0.4s; 
} 
  
.category-card:hover img{ 
transform:scale(1.05); 
opacity:0.9; 
} 
  
.category-overlay{ 
position:absolute; 
inset:0; 
background:linear-gradient(to top,rgba(0,0,0,0.72),rgba(0,0,0,0.12)); 
display:flex; 
flex-direction:column; 
justify-content:flex-end; 
padding:24px; 
} 
  
.category-badge{ 
display:inline-block; 
background:#fbbf24; 
color:#111827; 
padding:6px 12px; 
border-radius:999px; 
font-size:11px; 
font-weight:900; 
margin-bottom:14px; 
width:max-content; 
} 
  
.category-title{ 
font-size:28px; 
font-weight:900; 
color:white; 
line-height:1.2; 
} 
  
.category-desc{ 
margin-top:10px; 
font-size:13px; 
line-height:1.8; 
color:rgba(255,255,255,0.92); 
} 
  
/* ========================= 
PRODUITS 
========================= */ 
  
.products-grid{ 
display:grid; 
grid-template-columns:repeat(5,1fr); 
gap:22px; 
margin-top:40px; 
} 
  
.product-card{ 
background:white; 
border-radius:24px; 
overflow:hidden; 
border:1px solid #e2e8f0; 
transition:0.3s; 
box-shadow:0 6px 18px rgba(15,23,42,0.05); 
} 
  
.product-card:hover{ 
transform:translateY(-6px); 
box-shadow:0 16px 34px rgba(15,23,42,0.10); 
} 
  
.product-image{ 
aspect-ratio:1/1; 
background:#f8fafc; 
display:flex; 
align-items:center; 
justify-content:center; 
padding:18px; 
} 
  
.product-image img{ 
max-width:100%; 
max-height:100%; 
object-fit:contain; 
} 
  
.product-content{ 
padding:18px; 
} 
  
.product-badge{ 
display:inline-block; 
padding:6px 10px; 
border-radius:999px; 
font-size:10px; 
font-weight:900; 
text-transform:uppercase; 
margin-bottom:12px; 
} 
  
.badge-stock{ 
background:#dcfce7; 
color:#166534; 
} 
  
.badge-preco{ 
background:#dbeafe; 
color:#1d4ed8; 
} 
  
.product-title{ 
margin:0; 
font-size:14px; 
line-height:1.6; 
font-weight:800; 
color:#111827; 
min-height:46px; 
} 
  
.product-price{ 
margin-top:14px; 
font-size:24px; 
font-weight:900; 
color:#dc2626; 
} 
  
.product-button{ 
margin-top:16px; 
display:block; 
background:#111827; 
color:white; 
text-align:center; 
padding:12px; 
border-radius:14px; 
font-size:12px; 
font-weight:900; 
text-transform:uppercase; 
} 
  
/* ========================= 
BANNER 
========================= */ 
  
.banner{ 
margin-top:70px; 
background: 
linear-gradient(135deg,rgba(17,24,39,0.92),rgba(29,78,216,0.88)), 
url(''https://images.unsplash.com/photo-1520607162513-77705c0f0d4a?q=80&w=1600&auto=format&fit=crop'') center/cover; 
padding:70px 30px; 
border-radius:34px; 
text-align:center; 
color:white; 
overflow:hidden; 
position:relative; 
} 
  
.banner h2{ 
margin:0; 
font-size:48px; 
font-weight:900; 
line-height:1.1; 
} 
  
.banner p{ 
margin:24px auto 0 auto; 
max-width:760px; 
font-size:16px; 
line-height:2; 
color:rgba(255,255,255,0.92); 
} 
  
.banner-btn{ 
display:inline-block; 
margin-top:30px; 
background:#fbbf24; 
color:#111827; 
padding:16px 28px; 
border-radius:999px; 
font-size:13px; 
font-weight:900; 
text-transform:uppercase; 
} 
  
/* ========================= 
SEO 
========================= */ 
  
.seo{ 
margin:70px auto; 
max-width:950px; 
text-align:center; 
} 
  
.seo h2{ 
margin:0; 
font-size:34px; 
font-weight:900; 
color:#111827; 
} 
  
.seo p{ 
margin-top:22px; 
font-size:14px; 
line-height:2; 
color:#64748b; 
} 
  
/* ========================= 
RESPONSIVE 
========================= */ 
  
@media(max-width:1100px){ 
  
.products-grid{ 
grid-template-columns:repeat(3,1fr); 
} 
  
.categories-grid{ 
grid-template-columns:repeat(2,1fr); 
} 
  
.benefits-grid{ 
grid-template-columns:repeat(2,1fr); 
} 
  
} 
  
@media(max-width:768px){ 
  
.products-grid{ 
grid-template-columns:repeat(2,1fr); 
} 
  
.categories-grid{ 
grid-template-columns:1fr; 
} 
  
.benefits-grid{ 
grid-template-columns:1fr; 
} 
  
.hero{ 
padding:80px 20px; 
} 
  
.hero p{ 
font-size:16px; 
} 
  
.section-title{ 
font-size:30px; 
} 
  
.banner h2{ 
font-size:36px; 
} 
  
} 
  
@media(max-width:520px){ 
  
.products-grid{ 
grid-template-columns:1fr; 
} 
  
} 
  
</style> 
</head> 
  
