INSERT INTO "themes_template" VALUES(56,'Badge Satisfait ou Remboursé','<!-- =========================
BADGE SATISFAIT OU REMBOURSÉ
========================= -->

<div style="text-align:center; margin-bottom:50px;">

<svg width="200" height="230" viewBox="0 0 200 260" style="margin:0 auto; display:block;">

<defs>
  <radialGradient id="goldOuter" cx="40%" cy="35%" r="70%">
    <stop offset="0%" stop-color="#FEF3C7"/>
    <stop offset="45%" stop-color="#FBBF24"/>
    <stop offset="100%" stop-color="#B45309"/>
  </radialGradient>
  <radialGradient id="goldInner" cx="35%" cy="30%" r="75%">
    <stop offset="0%" stop-color="#FFFBEB"/>
    <stop offset="60%" stop-color="#FDE68A"/>
    <stop offset="100%" stop-color="#F59E0B"/>
  </radialGradient>
  <linearGradient id="leafGrad" x1="0%" y1="0%" x2="100%" y2="100%">
    <stop offset="0%" stop-color="#4ADE80"/>
    <stop offset="100%" stop-color="#15803D"/>
  </linearGradient>
  <linearGradient id="ribbonGrad" x1="0%" y1="0%" x2="0%" y2="100%">
    <stop offset="0%" stop-color="#EF4444"/>
    <stop offset="100%" stop-color="#B91C1C"/>
  </linearGradient>
  <filter id="softShadow" x="-50%" y="-50%" width="200%" height="200%">
    <feDropShadow dx="0" dy="3" stdDeviation="4" flood-color="#000000" flood-opacity="0.22"/>
  </filter>
</defs>

<g filter="url(#softShadow)">

  <g id="leaf-left">
    <path d="M 45.9,88.4 q -9,-2 -8,7 q 9,2 8,-7 Z" fill="url(#leafGrad)" transform="rotate(285 45.9 88.4)"/>
    <path d="M 42.8,98.5 q -9,-2 -8,7 q 9,2 8,-7 Z" fill="url(#leafGrad)" transform="rotate(272 42.8 98.5)"/>
    <path d="M 42.6,109.1 q -9,-2 -8,7 q 9,2 8,-7 Z" fill="url(#leafGrad)" transform="rotate(259 42.6 109.1)"/>
    <path d="M 45.6,119.7 q -9,-2 -8,7 q 9,2 8,-7 Z" fill="url(#leafGrad)" transform="rotate(246 45.6 119.7)"/>
    <path d="M 51.6,129.7 q -9,-2 -8,7 q 9,2 8,-7 Z" fill="url(#leafGrad)" transform="rotate(233 51.6 129.7)"/>
    <path d="M 60.5,138.5 q -10,-2 -9,8 q 10,2 9,-8 Z" fill="url(#leafGrad)" transform="rotate(219 60.5 138.5)"/>
    <path d="M 71.9,145.6 q -10,-2 -9,8 q 10,2 9,-8 Z" fill="url(#leafGrad)" transform="rotate(206 71.9 145.6)"/>
  </g>

