INSERT INTO "themes_template" VALUES(94,'PAGE VIP PREMIUM ANNEE 2','<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>PopLicence VIP Premium | Club VIP Premium Livraison & Avantages</title>

<meta name="description" content="Découvrez PopLicence VIP Premium : -5% permanent, livraisons Chronopost offertes, accès prioritaire aux nouveautés, avantages VIP et expérience premium pensée pour les passionnés de licences officielles.">

<style>

/* =========================
BASE
========================= */

body{
margin:0;
font-family:Arial,sans-serif;
background:#f8fafc;
color:#111827;
}

*{
box-sizing:border-box;
}

.container{
max-width:1200px;
margin:auto;
padding:0 20px;
}

/* =========================
HERO PREMIUM
========================= */

.hero-premium{
position:relative;
overflow:hidden;
padding:90px 20px 120px 20px;
background:
linear-gradient(135deg,rgba(15,23,42,0.96),rgba(30,58,138,0.92)),
url(''https://i.postimg.cc/zGBpBtyd/Gemini-Generated-Image-n6pjxtn6pjxtn6pj.png'') center/cover;
color:white;
text-align:center;
}

.hero-premium::before{
content:"";
position:absolute;
top:-120px;
right:-120px;
width:320px;
height:320px;
border-radius:50%;
background:rgba(255,255,255,0.05);
}

.hero-premium::after{
content:"";
position:absolute;
bottom:-100px;
left:-100px;
width:260px;
height:260px;
border-radius:50%;
background:rgba(255,255,255,0.04);
}

.hero-content{
position:relative;
z-index:2;
max-width:950px;
margin:auto;
}

.hero-badge{
display:inline-block;
background:#fbbf24;
color:#111827;
